insert into private.message_safety_rules select * from jsonb_populate_recordset(null::private.message_safety_rules, '[{"id":"sexual underwear","active":true,"pattern":"(?i)(worn|used)\\s+(underwear|underpants|panties|pants|socks|bra|swimsuit|swimwear|bathing suit)","category":"sexualized","severity":"block","created_at":"2026-11-14T15:44:30.069418+00:00","description":"requests for worn clothing items"},{"id":"sexual photos","active":true,"pattern":"(?i)(send|share|trade|sell)[^\\n]{0,80}\\y(selfies?|nudes?|naked)\\y","category":"sexualized","severity":"block","created_at":"2026-11-14T15:44:30.069418+00:00","description":"requests for selfies or explicit photos"},{"id":"personal photos","active":true,"pattern":"(?i)(send|share|trade|sell)[^\\n]{0,50}\\y(pics?|photos?|images?)\\y[^\\n]{0,30}\\y(of you|of yourself|yourself|your face|your body)\\y","category":"sexualized","severity":"block","created_at":"2026-11-14T15:44:30.069418+00:00","description":"requests for photos of the recipient"},{"id":"sexual payment","active":true,"pattern":"(?i)\\y(if you include|include your|add your|extra if you|pay (you )?(more )?(if|for))[^\\n]{0,80}\\y(pants|underwear|panties|nudes?|pics?|photos?)","category":"sexualized","severity":"block","created_at":"2026-11-14T15:44:30.069418+00:00","description":"payment offered for personal items or images"},{"id":"sexual words","active":true,"pattern":"(?i)\\y(nudes?|naked pics?|onlyfans|fansly|sugar (baby|daddy)|cam ?girl|escort|horny|sexy pics?|dick pic|sext(ing)?)\\y","category":"sexualized","severity":"block","created_at":"2026-11-14T15:44:30.069418+00:00","description":"explicit sexual terms"},{"id":"grooming secrecy","active":true,"pattern":"(?i)\\y(don.t tell (your )?(parents|mom|dad|guardian)|keep this (just )?between (us|me and you)|our (little )?secret)\\y","category":"grooming","severity":"block","created_at":"2026-11-14T15:44:30.069418+00:00","description":"secrecy pressure targeting minors"},{"id":"contact offplatform","active":true,"pattern":"(?i)\\y(dm me|hit me up|add me|hmu)[^\\n]{0,40}\\y(on|at|via|through)\\y[^\\n]{0,30}\\y(instagram|snap(chat)?|telegram|whatsapp|discord|tiktok|kik|signal|facebook|twitter|threads|cashapp|venmo|zelle)\\y","category":"offplatform","severity":"block","created_at":"2026-11-14T15:44:30.069418+00:00","description":"redirecting contact to off-platform socials"},{"id":"phone number","active":true,"pattern":"(?i)(call|text|ring|reach) me (at|on) [+.\\d][\\d .()-]{7,}","category":"offplatform","severity":"block","created_at":"2026-11-14T15:44:30.069418+00:00","description":"phone number sharing"},{"id":"handle request","active":true,"pattern":"(?i)\\ywhats your (snap|insta|instagram|telegram|number|phone)\\y","category":"offplatform","severity":"flag","created_at":"2026-11-14T15:44:30.069418+00:00","description":"requesting contact handles"},{"id":"links","active":true,"pattern":"(?i)https?://(?![^\\s]*mortapp)[a-z0-9-]+(\\.[a-z0-9-]+)+[^\\s]*","category":"offplatform","severity":"flag","created_at":"2026-11-14T15:44:30.069418+00:00","description":"external links"},{"id":"earnings lure","active":true,"pattern":"(?i)\\y(make|earn|get)\\s+\\$?\\d{3,}(\\+)?\\s*(a|per|each|every)?\\s*(day|week|month)?\\y","category":"financial","severity":"flag","created_at":"2026-11-14T15:44:30.069418+00:00","description":"unrealistic earnings offers"},{"id":"job bait","active":true,"pattern":"(?i)\\y(cash (in hand|only)|get (paid )?in (gift ?cards?|crypto)|modeling (job|gig)|photoshoot (job|gig))\\y","category":"financial","severity":"flag","created_at":"2026-11-14T15:44:30.069418+00:00","description":"common grooming/exploitation lures"},{"id":"number pattern","active":true,"pattern":"[+.\\d][\\d .()-]{8,}\\d","category":"offplatform","severity":"review","created_at":"2026-11-14T15:44:30.069418+00:00","description":"possible phone number"},{"id":"direct threats","active":true,"pattern":"(?i)(i will kill you|kill you|hurt you|beat you|i know where you live|i will find you|watching your house|bring a weapon|i have a gun)","category":"threats","severity":"block","created_at":"2026-11-14T15:55:50.159977+00:00","description":"direct threats or intimidation"},{"id":"coercion blackmail","active":true,"pattern":"(?i)(blackmail|expose you|post your photos|ruin you unless|pay me or|do this or else)","category":"coercion","severity":"block","created_at":"2026-11-14T15:55:50.159977+00:00","description":"blackmail and coercive threats"},{"id":"exact street address","active":true,"pattern":"(?i)(^|[^0-9])[0-9]{1,6}[[:space:]]+[a-z0-9.''-]+([[:space:]]+[a-z0-9.''-]+){0,4}[[:space:]]+(street|st|avenue|ave|road|rd|drive|dr|lane|ln|court|ct|boulevard|blvd|way|parkway|pkwy|place|pl)([^a-z]|$)","category":"personal_information","severity":"block","created_at":"2026-11-14T15:55:50.159977+00:00","description":"sharing an exact street address in job chat"},{"id":"sensitive information request","active":true,"pattern":"(?i)(send me|give me|what is|tell me).{0,50}(home address|school address|student number|social security|passport number|license number)","category":"personal_information","severity":"block","created_at":"2026-11-14T15:55:50.159977+00:00","description":"requests for sensitive identity or location data"},{"id":"unsafe payment pressure","active":true,"pattern":"(?i)(gift[[:space:]]*cards?|crypto payment|deposit first|upfront fee|cashapp|venmo|zelle|paypal|pay or else|withhold pay)","category":"financial","severity":"block","created_at":"2026-11-14T15:55:50.159977+00:00","description":"off-platform payment requests and unsafe payment pressure"},{"id":"harassment and humiliation","active":true,"pattern":"(?i)(you are worthless|stupid kid|stupid adult|hate you|i will humiliate you)","category":"harassment","severity":"flag","created_at":"2026-11-14T15:55:50.159977+00:00","description":"potential harassment or humiliation"}]'::jsonb);
