insert into public.legal_documents select * from jsonb_populate_recordset(null::public.legal_documents, '[{"id":"1f6a3eeb-9f2b-4a98-9c4c-1f9b2461eb10","title":"MORT Privacy Policy","created_at":"2026-10-29T00:13:51.418912+00:00","updated_at":"2026-10-29T01:18:15.85991+00:00","document_key":"privacy_policy","document_category":"privacy_policy","publication_status":"published","guardian_mode_independent":true},{"id":"e510f14e-bc8d-480b-9aff-1f761fac05bf","title":"MORT Safety Rules","created_at":"2026-10-29T00:13:51.418912+00:00","updated_at":"2026-10-29T01:18:15.85991+00:00","document_key":"safety_rules","document_category":"safety_rules","publication_status":"published","guardian_mode_independent":true},{"id":"a8bf022c-3981-4504-9d5e-30840ac0f0ac","title":"MORT Community Guidelines","created_at":"2026-10-29T00:13:51.418912+00:00","updated_at":"2026-10-29T01:18:15.85991+00:00","document_key":"community_guidelines","document_category":"community_guidelines","publication_status":"published","guardian_mode_independent":true},{"id":"332f598e-b4e6-4626-8c39-7b6fb2261064","title":"MORT Master Terms of Service","created_at":"2026-10-29T00:13:51.418912+00:00","updated_at":"2026-11-11T11:46:49.232363+00:00","document_key":"master_terms_of_service","document_category":"terms_of_service","publication_status":"published","guardian_mode_independent":true}]'::jsonb);
